// ❌ Enfoque hardcoded: datos mezclados con lógica
public class Enemy : MonoBehaviour
{
    void Start()
    {
        hp = 100;          // ← dato hardcodeado
        speed = 3.5f;      // ← dato hardcodeado
        damage = 25;       // ← dato hardcodeado
        attackRate = 1.2f; // ← dato hardcodeado
    }
}

// ✅ Enfoque Data Driven: lógica separada de datos
[System.Serializable]
public class EnemyData
{
    public int hp;
    public float speed;
    public int damage;
    public float attackRate;
}

public class Enemy : MonoBehaviour
{
    public EnemyData data; // datos vienen de fuera (JSON / ScriptableObject)

    void Start()
    {
        // La lógica usa los datos, pero no los define
        ApplyStats(data);
    }
}

